@Entity('users')
export class UserEntity {
  @PrimaryColumn({ unique: true })
  id: string;
  @Column()
  password: string;
  @Column({ readonly: true, default: BOType.USERS })
  objectType: string;
  @Column({ nullable: true })
  roles: string;
  @Column({ default: false })
  locked: boolean;
  @CreateDateColumn()
  createdAt: Date;
  @UpdateDateColumn()
  changedAt: Date;

  @OneToOne(() => UserProfileEntity, { cascade: true, onDelete: 'CASCADE' })
  @JoinColumn()
  profile: UserProfileEntity;

  @Index({ unique: false })
  @ManyToOne(() => OrganizationEntity, organization => organization.users)
  organization: OrganizationEntity;

  @BeforeInsert()
  async hashPassword() {
    this.password = await bcrypt.hash(this.password, 10);
  }

  toDTO(): UserDTO {
    const { password, createdAt, changedAt, roles, organization, ...dto } = this;
    const rolesArray = roles.split(',').map(r => r.trim());
    const orgId = organization.id || undefined;
    return { ...dto, orgId, roles: rolesArray } as UserDTO;
  }
}

