import { InMemoryDBService } from '@nestjs-addons/in-memory-db';
import { ShortUrlEntity } from './shortUrl.entity';
import { HttpException, HttpStatus, Injectable } from '@nestjs/common';
import {
  buildSuccessResponse,
  generateShortUrl,
  isValidShortUrl,
  isValidUrl,
} from '../util';

@Injectable()
export class ShortUrlService {
  constructor(
    private readonly shortUrlEntityInMemoryDBService: InMemoryDBService<ShortUrlEntity>,
  ) {}

  encode(url: string): { data: { [p: string]: any }; status: string } {
    const validUrl = isValidUrl(url);
    // check if URL is valid
    if (!validUrl)
      throw new HttpException('Invalid URL specified', HttpStatus.BAD_REQUEST);

    // check if url has been previously stored
    const [encodedUrl] = this.shortUrlEntityInMemoryDBService.query(
      (record) => record.originalUrl === url,
    );

    if (encodedUrl)
      throw new HttpException(
        'URL has already been shortened',
        HttpStatus.CONFLICT,
      );

    const shortUrl = generateShortUrl();

    this.shortUrlEntityInMemoryDBService.create({ originalUrl: url, shortUrl });
    return buildSuccessResponse({ shortUrl });
  }

  decode(url: string): { data: { [p: string]: any }; status: string } {
    const validShortUrl = isValidShortUrl(url);

    if (!validShortUrl)
      throw new HttpException(
        'Invalid Short URL specified',
        HttpStatus.BAD_REQUEST,
      );

    const [decodedUrl] = this.shortUrlEntityInMemoryDBService.query(
      (record) => record.shortUrl === url,
    );

    if (!decodedUrl)
      throw new HttpException(
        'URL matching short URL not found',
        HttpStatus.NOT_FOUND,
      );

    return buildSuccessResponse({ originalUrl: decodedUrl.originalUrl });
  }
}

