          }
        }
      } catch (e) {
        next(e);
      }
    } else {
      errors.push('username is required');
    }

    // email is required, must be a valid email and unique
    if (email) {
      if (!email.trim()) {
        errors.push('email can not be empty');
      }

      const emailRegex = /^([a-zA-Z0-9+.-]{2,})@([a-zA-Z0-9-]{2,})\.([a-zA-Z0-9]{2,6})/g;
