            _ctx.Users.Add(user);
        }

        public void Update(User user)
        {
            _ctx.Entry(user).State = EntityState.Modified;
        }

        public void Delete(User user)
        {
            _ctx.Users.Remove(user);
        }

        public IEnumerable<BankAccount> GetBankAccounts()
        {
